// Bibliothèque des stratégies de donjons VIGIE. Les cartes sont des schémas tactiques originaux, simplifiés et sans échelle.
const DONJONS=[{"id":"shattered-throne","name":"Le Trône brisé","original":"The Shattered Throne","summary":"Un parcours dans la Cité des Rêves, avec une route de symboles, puis deux combats de boss.","source":"https://destiny2.vaexil.tv/guides/dungeons/the-shattered-throne","route":["Dans le grand labyrinthe d’Erebus, les groupes d’ennemis appelés Architectes révèlent le symbole de la prochaine tour. Lis-le à chaque arrêt : l’ordre n’est pas fixe.","Entre les combats, avance de plateforme en plateforme et élimine les tireurs avant de sauter. Dans le couloir ralenti, continue d’avancer et utilise les alcôves comme abri."],"encounters":[{"title":"Erebus — suivre les symboles","goal":"Éliminer les groupes Architectes dans le bon ordre et retrouver la tour indiquée par chaque nouveau symbole.","team":"À trois : un Gardien lit et annonce les symboles, les deux autres nettoient les tireurs et couvrent les déplacements. À un ou deux, restez ensemble et lisez le symbole avant chaque trajet.","steps":["À l’entrée, éliminez le groupe pris dans la structure du labyrinthe. Quand il est vaincu, un emblème apparaît : c’est la destination suivante, pas une récompense à ramasser.","Annonce le nom ou la forme complète du symbole. Si personne ne sait le nom, décrivez-le et comparez-le à l’enseigne des bâtiments avant de partir.","Rejoignez le bâtiment qui porte ce symbole. Empruntez les escaliers et les ponts visibles plutôt que de tenter des sauts courts au-dessus du vide ; éliminez les tireurs sur les toits.","Dans le bâtiment, éliminez le groupe Architecte pour obtenir le prochain emblème, puis recommencez. Le symbole du prochain trajet peut changer d’une partie à l’autre.","Quand apparaît l’oiseau plongeant, retournez au bâtiment Ingress, celui du départ. Éliminez le dernier groupe pour ouvrir la sortie vers la suite du donjon."],"recovery":"Si le groupe s’est perdu, revenez au dernier bâtiment nettoyé et relisez son symbole. Ne suivez pas une séquence mémorisée d’une autre partie.","map":{"title":"La route dépend du symbole révélé","nodes":[{"p":"entry","label":"Départ|Ingress","kind":"entry"},{"p":"center","label":"Ville|Erebus","kind":"room"},{"p":"nw","label":"Tour|symbole 1","kind":"goal"},{"p":"ne","label":"Tour|symbole 2","kind":"goal"},{"p":"sw","label":"Toits|passage sûr","kind":"safe"},{"p":"se","label":"Retour|oiseau plongeant","kind":"goal"}],"links":[["entry","center"],["center","nw"],["nw","ne"],["ne","sw"],["sw","se"],["se","entry"]]}},{"title":"Vorgeth — les quatre Gardiennes","goal":"Vaincre les quatre Gardiennes, récupérer leurs marques à temps, purifier un sceau central et profiter de la fenêtre de dégâts.","team":"À trois : un joueur affaiblit les Gardiennes, un suit le chronomètre et l’ordre des coins, un nettoie les ennemis et les projectiles. Un seul joueur peut faire le tour, mais il doit préparer les cibles avant de prendre la première marque.","steps":["Depuis les escaliers d’entrée, repère les quatre coins de l’arène. Chaque coin contient une Sorcière Gardienne protégée par des ennemis ; élimine d’abord les gêneurs et affaiblis chaque Gardienne sans ramasser sa marque.","Quand les quatre cibles sont prêtes, choisis un trajet autour du bord qui se termine près d’un sceau au pied du bassin central. Annonce qui prend la première marque.","Tue une Gardienne et ramasse sa marque : le compte à rebours commence. Passe immédiatement à la suivante et récupère chaque marque avant la fin du temps.","La quatrième marque donne l’état nécessaire pour purifier un des sceaux autour du bassin. Interagis avec le sceau et vérifie que le bouclier de Vorgeth tombe.","Fais les dégâts depuis un emplacement avec un pilier entre toi et le boss si nécessaire. Tire aussi sur les projectiles violets qui poursuivent l’équipe.","Quand Vorgeth redevient immunisé, recule vers le bord, élimine les ennemis et recommence le circuit."],"recovery":"Ne ramasse pas la première marque avant d’avoir préparé les quatre Sorcières : le chronomètre rendrait la tournée beaucoup plus difficile. Si le temps est perdu, stabilise l’arène puis repars de zéro.","map":{"title":"Quatre coins, un bassin central","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Vorgeth|bassin","kind":"boss"},{"p":"nw","label":"Gardienne|1","kind":"goal"},{"p":"ne","label":"Gardienne|2","kind":"goal"},{"p":"sw","label":"Gardienne|3","kind":"goal"},{"p":"se","label":"Gardienne|4","kind":"goal"},{"p":"north","label":"Sceau|à purifier","kind":"safe"}],"links":[["entry","nw"],["nw","ne"],["ne","se"],["se","sw"],["sw","north"],["north","center"]]}},{"title":"Dûl Incaru — trois Chevaliers","goal":"Éliminer les Psions avant qu’ils ne se multiplient, récupérer les trois charges des Chevaliers puis vaincre Dûl Incaru pendant qu’elle est vulnérable.","team":"À trois : chacun surveille un Chevalier ; le groupe annonce les Psions et se regroupe près du boss lorsque les charges sont prêtes. À un ou deux, nettoie les Psions entre chaque déplacement.","steps":["Élimine rapidement les petits Psions : s’ils restent en vie, ils se divisent et saturent la salle. Garde les abris au centre pour te protéger des tirs.","Affaiblis les trois Fatesmith Knights. Ne ramasse pas les charges tant que les Psions proches et les tirs dangereux n’ont pas été maîtrisés.","Tue les Chevaliers et ramasse leurs charges Finite Thought. Chaque charge augmente l’effet qui permet de blesser le boss ; appelle ton nombre à l’équipe.","Avec les trois charges, concentre les dégâts sur Dûl Incaru. Utilise le brasero central pour te purifier avant l’expiration du buff, comme indiqué par le jeu.","Si le boss survit, les charges et les ennemis reviennent : nettoie d’abord les Psions, puis prépare le prochain cycle."],"recovery":"Si le buff expire ou si tu meurs avant les dégâts, ne poursuis pas le boss pendant qu’il est immunisé. Reviens derrière un pilier, élimine les Psions et refais le cycle.","map":{"title":"Rester au centre, surveiller trois côtés","nodes":[{"p":"entry","label":"Escaliers","kind":"entry"},{"p":"center","label":"Dûl Incaru","kind":"boss"},{"p":"nw","label":"Chevalier|gauche","kind":"goal"},{"p":"ne","label":"Chevalier|droite","kind":"goal"},{"p":"north","label":"Chevalier|fond","kind":"goal"},{"p":"south","label":"Brasero|purification","kind":"safe"}],"links":[["entry","south"],["south","center"],["center","nw"],["center","ne"],["center","north"]]}}]},{"id":"pit-of-heresy","name":"Fosse de l’hérésie","original":"Pit of Heresy","summary":"Un donjon de la Ruche : reliques-épées, charges abyssales et traversées de pièges.","source":"https://destiny2.vaexil.tv/guides/dungeons/pit-of-heresy","route":["Après la Nécropole, descends par les plateformes larges du Mur des portes. Les portes avec des runes suspendues peuvent déclencher des pièges qui projettent dans le vide.","Dans les Tunnels, les grands Ogres sont invulnérables. Passe par les petites grottes protégées, puis sors seulement quand l’Ogre regarde ailleurs.","Après la Chambre, mémorise les trois runes pendant la descente du Harrow. Les tours avec ces symboles sont la destination ; ne traverse pas les pièges en courant."],"encounters":[{"title":"La Nécropole — les trois disciples","goal":"Lire trois runes, trouver les tours correspondantes et vaincre un disciple avec la bonne attaque de l’épée de la Ruche.","team":"À trois : un lecteur note les runes, un porte l’épée, un escorte et élimine Ogres et ennemis. Changez de porteur si son épée expire.","steps":["Depuis le rebord, lis les trois runes enchaînées affichées à l’entrée et répète-les à voix haute. Une tour est correcte uniquement si sa rune correspond à l’une de celles-ci.","Élimine un Swordbearer (grand Chevalier porteur d’épée) et ramasse sa relique. Avant d’entrer dans la tour, identifie si le disciple est un Chevalier, une Sorcière ou un Shrieker.","Contre un Chevalier, utilise les coups rapides de l’épée ; contre une Sorcière, lance l’attaque lourde à distance ; contre un Shrieker, lève la garde face à ses projectiles pour les renvoyer.","Quand le disciple meurt, une chaîne se casse. Sors, retrouve l’une des autres runes de l’entrée et répète avec une nouvelle épée si besoin.","Après les trois victoires, suis le faisceau vert vertical : il indique le passage ouvert."],"recovery":"Une tour incorrecte ne fait pas progresser. Si l’épée s’épuise, élimine un autre porteur d’épée ; les disciples déjà vaincus restent validés.","map":{"title":"Trois tours reliées au départ","nodes":[{"p":"entry","label":"Salle des|runes","kind":"entry"},{"p":"center","label":"Nécropole","kind":"room"},{"p":"nw","label":"Tour|Chevalier","kind":"goal"},{"p":"ne","label":"Tour|Sorcière","kind":"goal"},{"p":"north","label":"Tour|Shrieker","kind":"goal"},{"p":"south","label":"Descente|faisceau vert","kind":"safe"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","north"],["center","south"]]}},{"title":"Les Tunnels du désespoir — trois portes","goal":"Dans les grottes sûres, vaincre trois Chevaliers, transporter leurs charges du Vide et ouvrir les grilles malgré les Ogres invulnérables.","team":"À trois : un joueur repère le trajet, un attire l’attention de l’Ogre, un transporte la charge. En solo, attends le passage de l’Ogre dans la grotte au lieu de tenter de le combattre.","steps":["Depuis la première bifurcation, entre dans une petite grotte couverte d’une membrane. Les grands Ogres ne peuvent pas y pénétrer ; élimine les Thralls et le Chevalier à l’intérieur.","Ramasse la charge du Vide laissée par le Chevalier, mais ne sors pas avant d’avoir repéré l’Ogre et la grille à ouvrir.","Attends que l’Ogre regarde ailleurs ou attire-le à l’opposé. Traverse directement vers le réceptacle de la grille et dépose la charge.","La grille ouverte est permanente. Reviens par les grottes, répète pour les deux autres Chevaliers et évite les longues voies principales tant que l’Ogre les patrouille.","Après le troisième dépôt, laisse les Ogres se retirer puis continue vers la Chambre de souffrance."],"recovery":"Ne tire pas sur les Ogres : ils sont invulnérables dans cette étape. Si le porteur meurt, l’équipe revient par les grottes et refait le Chevalier concerné.","map":{"title":"Réseau de grottes et trois grilles","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Voies des|Ogres","kind":"danger"},{"p":"nw","label":"Grotte sûre|Chevalier 1","kind":"safe"},{"p":"ne","label":"Grotte sûre|Chevalier 2","kind":"safe"},{"p":"sw","label":"Grotte sûre|Chevalier 3","kind":"safe"},{"p":"south","label":"Grilles|de sortie","kind":"goal"}],"links":[["entry","nw"],["nw","center"],["center","ne"],["center","sw"],["sw","south"],["ne","south"]]}},{"title":"Chambre de souffrance — six charges","goal":"Empêcher le Totem d’anéantissement de se charger, déposer six charges et maîtriser les vagues de Chevaliers et de Thralls.","team":"À trois : une personne reste près de la plaque centrale, deux font les trajets vers les Chevaliers éloignés. La personne sur la plaque nettoie les ennemis proches et annonce tout danger.","steps":["Démarre sur la plaque centrale et repère le Totem au-dessus. Un Gardien doit rester sur ou juste autour de la plaque pour l’empêcher de se charger jusqu’à l’élimination de l’équipe.","Un coureur affaiblit puis tue un Chevalier hérétique sur une passerelle éloignée, prend sa charge du Vide et revient au réceptacle près de la sortie.","Dépose une seule charge à la fois. Chaque dépôt enlève un verrou de sortie et remet à zéro la malédiction de souffrance, qui augmente les dégâts subis.","Après chaque dépôt, nettoie les ennemis qui apparaissent, surtout les Chevaliers tireurs en hauteur, les Thralls maudits et ceux qui foncent sur la plaque.","Alterne les côtés ou choisis le Chevalier le plus sûr. Recommence jusqu’à six dépôts et vérifie que le passage s’ouvre."],"recovery":"Si le Totem commence à briller et à se charger, retourne immédiatement à la plaque. Si la malédiction est élevée, termine le dépôt préparé avant de lancer une nouvelle longue sortie.","map":{"title":"Plaque centrale à tenir","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Plaque +|Totem","kind":"goal"},{"p":"nw","label":"Chevalier|gauche","kind":"danger"},{"p":"ne","label":"Chevalier|droite","kind":"danger"},{"p":"north","label":"Sortie|6 verrous","kind":"goal"},{"p":"sw","label":"Balcon|tireurs","kind":"danger"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","north"],["center","sw"]]}},{"title":"Le Harrow — trois runes dans le labyrinthe","goal":"Mémoriser trois runes en descendant, puis traverser le parcours piégé et vaincre les trois Sorcières des tours correspondantes.","team":"À trois : un joueur rappelle les runes, les autres avancent par étapes et éliminent les ennemis dans les tours. Attendez que les pièges aient terminé un cycle avant de franchir une zone.","steps":["Au début de la descente, ne tombe pas immédiatement : regarde le mur et note les trois grandes runes de la Ruche. Répète-les avant d’entrer dans le labyrinthe.","Progresse de plateforme stable en plateforme stable. Observe les barres à pointes, murs écrasants et jets de flammes au moins une fois avant de traverser.","Cherche les tours dont l’entrée porte l’une des runes notées. Dans chaque tour, élimine les Acolytes puis la Sorcière rituelle pour briser le sceau correspondant.","Retourne au trajet sûr après chaque tour et répète pour les deux autres runes. Ne te précipite pas dans une voie piégée pour gagner quelques secondes.","Quand les trois sceaux sont cassés, suis l’ouverture vers le Cradle of Damnation et prépare-toi au boss."],"recovery":"Si une rune a été ratée, remonte à la dernière corniche sûre et relis-la. Une tour non correspondante ne fera pas avancer le donjon.","map":{"title":"Un trajet piégé entre trois tours","nodes":[{"p":"entry","label":"Chambre|de souffrance","kind":"entry"},{"p":"center","label":"Passage|piégé","kind":"danger"},{"p":"nw","label":"Tour|rune 1","kind":"goal"},{"p":"ne","label":"Tour|rune 2","kind":"goal"},{"p":"north","label":"Tour|rune 3","kind":"goal"},{"p":"south","label":"Cradle|du boss","kind":"safe"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","north"],["center","south"]]}},{"title":"Zulmak — disciples et zone de dégâts","goal":"Vaincre trois disciples avec les bonnes attaques d’épée, déposer leurs charges au centre, puis faire les dégâts dans l’anneau sans rester pendant l’explosion.","team":"À trois : un porteur d’épée, un coureur de charge, un Gardien qui défend le centre. Avant le troisième dépôt, annoncez que tout le monde est prêt : il déclenche les dégâts.","steps":["Nettoie le centre et tue un Swordbearer. Prends son épée puis choisis un disciple extérieur : Chevalier, Sorcière ou Shrieker.","Utilise l’action correcte de l’épée : coups rapides sur le Chevalier, attaque lourde à distance sur la Sorcière, garde face au Shrieker pour renvoyer ses tirs.","À la mort du disciple, récupère la charge du Vide et dépose-la au piédestal correspondant au centre. Élimine les nouvelles vagues avant de partir vers le prochain disciple.","Répète pour les trois disciples. Le dernier dépôt fait tomber le bouclier de Zulmak : toute l’équipe se place dans l’anneau central et attaque.","Surveille les flammes au sol et la posture de Zulmak. Quand il s’agenouille et que le cristal se charge, quitte complètement l’anneau avant l’explosion."],"recovery":"Si le dernier dépôt a été fait avant que l’équipe soit prête, la survie passe avant les dégâts. Si Zulmak reste vivant après l’explosion, recommence le cycle avec les disciples.","map":{"title":"Trois disciples, centre dangereux","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Zulmak|anneau DPS","kind":"boss"},{"p":"nw","label":"Chevalier|épée","kind":"goal"},{"p":"ne","label":"Sorcière|épée","kind":"goal"},{"p":"sw","label":"Shrieker|épée","kind":"goal"},{"p":"south","label":"Piédestaux|de charge","kind":"safe"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","sw"],["nw","south"],["ne","south"],["sw","south"]]}}]},{"id":"prophecy","name":"Prophétie","original":"Prophecy","summary":"Utiliser l’ombre et la lumière pour créer les bonnes motes, purifier les colonnes et atteindre les boss.","source":"https://destiny2.vaexil.tv/guides/dungeons/prophecy","route":["Dans le désert, suis la lumière de Toland, la petite flamme blanche flottante, plutôt que de choisir une destination au hasard. Élimine les tireurs avant les sauts.","Les petites sphères laissées par les Chevaliers ne sont pas toutes identiques : le dernier coup doit être porté dans la bonne zone lumineuse pour produire des motes claires ou sombres."],"encounters":[{"title":"Phalanx Echo — les quatre colonnes","goal":"Produire des motes claires ou sombres, purifier les quatre colonnes correspondantes et attaquer le Phalanx Echo.","team":"À trois : un Gardien crée les motes, un élimine les Psions qui se divisent, un protège le coureur et le bord de l’arène.","steps":["Regarde les quatre colonnes autour de l’arène. La lumière ou l’ombre qui les recouvre indique quel type de motes il faut déposer.","Tue un Chevalier Taken près d’une zone éclairée ou très sombre. Le dernier coup porté dans cette lumière détermine les motes qu’il laisse ; vérifie leur apparence avant de les ramasser.","Ramasse cinq motes du type demandé, puis dépose-les sur la colonne qui porte la même illumination. Un seul dépôt correct efface cette colonne.","Répète jusqu’à ce que les quatre colonnes soient purifiées. Pendant ce temps, élimine les Psions avant qu’ils ne se dupliquent et garde un œil sur le bouclier du boss.","Quand le bouclier disparaît, fais les dégâts au Phalanx. S’il survit, reprends le cycle des colonnes."],"recovery":"Des motes claires ne purifient pas une colonne sombre, et inversement. Si tu as le mauvais type, attends une nouvelle occasion et refais le Chevalier au bon endroit.","map":{"title":"Colonnes autour du Phalanx","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Phalanx|Echo","kind":"boss"},{"p":"nw","label":"Colonne|claire","kind":"goal"},{"p":"ne","label":"Colonne|sombre","kind":"goal"},{"p":"sw","label":"Colonne|sombre","kind":"goal"},{"p":"se","label":"Colonne|claire","kind":"goal"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","sw"],["center","se"]]}},{"title":"Hexaèdre — orienter le cube","goal":"Purifier la colonne du côté où apparaît Toland pour faire tourner la salle, puis finir la séquence de six orientations.","team":"À trois : un lecteur repère Toland, un coureur crée les motes demandées, un Gardien tient les ennemis et les Psions. Dites « haut, bas, gauche, droite » selon le mur réel, pas selon votre écran.","steps":["Dans chaque salle carrée, élimine les ennemis et repère la petite lumière blanche de Toland sur l’un des murs. Elle indique la face à activer pour réorienter le cube.","Lis si la colonne de cette face exige lumière ou ombre. Tue les Chevaliers avec le dernier coup dans une zone claire ou sombre pour obtenir le type de motes correct.","Ramasse cinq motes, rejoins cette colonne et dépose-les. Le cube pivote ; ne quitte pas la salle avant que le déplacement soit confirmé.","Répète la lecture de Toland et le dépôt dans chaque orientation. Il faut réussir six orientations ; ne mémorise pas une séquence fixe.","Après la sixième, élimine les deux Centurions qui apparaissent pour terminer la rencontre."],"recovery":"Si Toland n’est plus visible, élimine les ennemis et inspecte chaque mur depuis le centre. Si le cube ne tourne pas, vérifie type et quantité de motes avant d’en refaire.","map":{"title":"Cube orientable, six faces","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Cube|arène","kind":"room"},{"p":"north","label":"Toland|face active","kind":"goal"},{"p":"west","label":"Colonnes|claire / sombre","kind":"goal"},{"p":"east","label":"Colonnes|claire / sombre","kind":"goal"},{"p":"south","label":"Centurions|après 6 tours","kind":"danger"}],"links":[["entry","center"],["center","north"],["center","west"],["center","east"],["center","south"]]}},{"title":"Kell Echo — les trois salles et le couloir","goal":"Dissiper les trois copies du boss, ouvrir le portail central et blesser le vrai Kell Echo pendant qu’il remonte le couloir sombre.","team":"À trois : un joueur garde les appels de lumière/ombre, deux éliminent les copies et les ennemis. Pour les dégâts, restez en groupe et avancez ensemble dans le couloir.","steps":["Dans la salle triangulaire, élimine les Psions puis tue les Chevaliers. Leur lumière au moment du dernier coup détermine le type de motes qu’ils laissent.","Purifie les trois colonnes des coins avec le bon type de motes. Chaque dépôt retire une copie de Kell Echo et ouvre progressivement le portail central.","Quand les trois copies ont disparu, traverse le portail pour rejoindre le couloir où se trouve le vrai boss. Commence les dégâts dès qu’il est vulnérable.","Avance derrière Kell Echo sans rester loin : l’effet Ténèbres envahissantes augmente si tu es séparé du boss. Tue les tireurs et les Chevaliers qui apparaissent sur le trajet.","Quand Kell Echo atteint la fin du couloir ou redevient immunisé, la phase s’arrête. Retourne dans une nouvelle salle triangulaire et répète."],"recovery":"Si tu es trop loin du boss dans le couloir, recolle-toi à lui et élimine les tireurs qui bloquent le déplacement. Une motte de mauvaise couleur doit être refaite depuis un Chevalier.","map":{"title":"Trois purifications puis couloir","nodes":[{"p":"entry","label":"Salle|triangulaire","kind":"entry"},{"p":"center","label":"Portail|central","kind":"goal"},{"p":"nw","label":"Colonne|1","kind":"goal"},{"p":"ne","label":"Colonne|2","kind":"goal"},{"p":"south","label":"Colonne|3","kind":"goal"},{"p":"north","label":"Couloir|Kell Echo","kind":"boss"}],"links":[["entry","nw"],["entry","ne"],["entry","south"],["nw","center"],["ne","center"],["south","center"],["center","north"]]}}]},{"id":"grasp-of-avarice","name":"Étreinte de l’avarice","original":"Grasp of Avarice","summary":"Accumuler des engrammes maudits, les déposer au cristal et se servir des canons Scorch.","source":"https://destiny2.vaexil.tv/guides/dungeons/grasp-of-avarice","route":["Dans la caverne d’ouverture, les coffres piégés sont un leurre : ouvre seulement le coffre qui ne déclenche pas le piège et suis l’indication du jeu.","Pendant la course de moineaux, active les mines dans l’ordre en traversant leurs zones avant l’explosion. Prends les leviers de temps sur la route si tu peux, mais reste sur la piste.","Un Vandal avec un canon Scorch peut laisser une arme : son tir chargé ouvre un mécanisme plus longtemps qu’un tir instantané."],"encounters":[{"title":"Phry’zhia — charger le cristal","goal":"Ramasser les engrammes maudits dans les salles latérales et les déposer au cristal central pour faire tomber le bouclier de Phry’zhia.","team":"À trois : un porteur du canon ouvre les portes, un coureur ramasse les engrammes, un défenseur protège le cristal et surveille le boss.","steps":["Nettoie les ennemis d’ouverture et élimine le Vandal avec canon Scorch. Ramasse son canon et tire sur le générateur au-dessus d’une porte latérale ; maintiens le tir pour obtenir une charge complète.","Entre dans la salle ouverte, élimine les ennemis de la Ruche et collecte les engrammes lumineux. Ils donnent le buff Burdened by Riches et un compte à rebours.","Sors avant que la porte ne se referme et reste dans l’aura du cristal central jusqu’à ce que ton compte à rebours disparaisse. Les engrammes sont déposés pour charger le cristal.","Répète dans l’autre salle latérale. Quand le cristal a absorbé suffisamment d’engrammes, le bouclier de Phry’zhia tombe : regroupe-toi et inflige des dégâts.","Quand le boss redevient immunisé, nettoie le centre et refais l’aller-retour canon, engrammes, cristal."],"recovery":"Si un porteur meurt, ses charges disparaissent : ne disperse pas les engrammes au sol. Dépose-les dans l’aura avant de repartir vers l’autre salle.","map":{"title":"Deux salles nourrissent le cristal","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Cristal|central","kind":"goal"},{"p":"nw","label":"Salle Ruche|gauche","kind":"room"},{"p":"ne","label":"Phry’zhia","kind":"boss"},{"p":"sw","label":"Salle Ruche|droite","kind":"room"},{"p":"south","label":"Générateur|canon Scorch","kind":"goal"}],"links":[["entry","south"],["south","nw"],["nw","center"],["center","sw"],["sw","center"],["center","ne"]]}},{"title":"Bouclier déchu — quatre générateurs","goal":"Désactiver quatre nœuds autour d’un bouclier en lançant les carcasses de Serviteurs dans les canons de lancement.","team":"À trois : un opérateur utilise le canon, deux nettoient les îlots et escortent le Serviteur. Changez de côté après chaque tir.","steps":["Tue les Vandals avec canon Scorch et choisis un îlot extérieur. Charge le canon en maintenant la gâchette sur le générateur jusqu’à ce qu’il soit activé.","Élimine les ennemis de l’îlot et le Serviteur. Quand sa coque est désactivée, pousse-la ou transporte-la jusqu’au canon de lancement.","Oriente le canon vers l’un des quatre nœuds du grand bouclier central et tire pour envoyer la coque dedans. Vérifie visuellement que le nœud s’éteint.","Répète sur les autres îlots jusqu’à ce que les quatre nœuds soient détruits. Les canons changent la direction du tir : regarde leur orientation avant de charger.","Le bouclier s’ouvre ; utilise le passage vers la suite et élimine les ennemis sur les plateformes."],"recovery":"Si le Serviteur part dans la mauvaise direction, vérifie la rotation du canon avant de recommencer. Garde un canon Scorch vivant ou repère un Vandal pour récupérer une nouvelle arme.","map":{"title":"Îlots en anneau, bouclier au milieu","nodes":[{"p":"entry","label":"Départ","kind":"entry"},{"p":"center","label":"Bouclier|central","kind":"goal"},{"p":"nw","label":"Îlot 1|Serviteur","kind":"room"},{"p":"ne","label":"Îlot 2|Serviteur","kind":"room"},{"p":"sw","label":"Îlot 3|Serviteur","kind":"room"},{"p":"se","label":"Îlot 4|Serviteur","kind":"room"}],"links":[["entry","nw"],["nw","center"],["entry","ne"],["ne","center"],["entry","sw"],["sw","center"],["entry","se"],["se","center"]]}},{"title":"Avarokk — charger le cristal et survivre","goal":"Collecter assez d’engrammes maudits, les déposer au cristal, puis attaquer Avarokk et ses lieutenants pendant l’ouverture.","team":"À trois : un porteur gère le canon, un court autour des distributeurs d’engrammes, un contrôle Avarokk et les ennemis. L’équipe doit annoncer le dépôt pour éviter que plusieurs porteurs meurent avec leurs charges.","steps":["Élimine un Vandal au canon Scorch et utilise son tir chargé sur le générateur pour libérer des vagues d’engrammes.","Ramasse les engrammes et transporte-les vers le cristal au centre. Reste dans son aura jusqu’à la disparition de toutes les charges maudites.","Quand le cristal valide la charge demandée, Avarokk devient vulnérable. Place-toi au point de dégâts convenu et tire sans rester près de son attaque de zone.","Élimine les lieutenants et ennemis qui mettent la pression sur l’équipe. S’ils interrompent la phase ou que le boss redevient immunisé, reprends le canon et relance le cycle.","Continue jusqu’à la défaite d’Avarokk. Ne considère jamais un engramme lumineux comme un butin : c’est une charge temporaire de mécanique."],"recovery":"Si le cristal ne progresse pas, vérifie que tu es dans son aura et que le buff descend. Si l’équipe est débordée, arrête la collecte, nettoie la salle, puis reprends.","map":{"title":"Cristal au centre, boss à distance","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Cristal|de dépôt","kind":"goal"},{"p":"north","label":"Avarokk","kind":"boss"},{"p":"nw","label":"Distributeur|gauche","kind":"room"},{"p":"ne","label":"Distributeur|droite","kind":"room"},{"p":"south","label":"Canon Scorch","kind":"goal"}],"links":[["entry","center"],["center","north"],["center","nw"],["center","ne"],["entry","south"],["south","nw"],["south","ne"]]}}]},{"id":"duality","name":"Dualité","original":"Duality","summary":"Alterner entre le monde matériel et le Cauchemar au son des cloches, avec un chronomètre dangereux.","source":"https://destiny2.vaexil.tv/guides/dungeons/duality","route":["Les cloches changent de monde. En monde matériel, tous les joueurs doivent être dans le cercle de la cloche avant de la tirer pour partir au Cauchemar ; si la cloche est tirée depuis le Cauchemar, une cloche de retour doit être atteinte par tous.","Le compte à rebours du Cauchemar est mortel. Tue les Porteurs de bannière utiles, puis élimine les Bellkeepers qui défendent la cloche de retour et regroupe-toi dans son cercle."],"encounters":[{"title":"Gahlran — récupérer deux bannières","goal":"Repérer les symboles demandés, tuer les Porteurs correspondants dans le Cauchemar, ouvrir deux salles et éliminer les Visions de Gahlran.","team":"À trois : un joueur par côté récupère une bannière ; le troisième nettoie le centre et les Bellkeepers. La priorité est de sortir du Cauchemar avant la fin du minuteur.","steps":["Dans la salle matérielle, lis les deux symboles au-dessus des portes à ouvrir. Annonce-les avant de tirer la cloche d’entrée.","Dans le Cauchemar, trouve les Porteurs des symboles demandés et tue uniquement ceux qui correspondent. Ramasse leurs essences de bannière puis rejoins la cloche de retour.","Place tous les joueurs vivants dans le cercle marqué de la cloche et tire-la pour revenir au monde matériel.","Dépose chaque bannière sur le symbole correspondant. Les deux portes latérales s’ouvrent ; place les joueurs qui vont les nettoyer avant la prochaine transition.","Tire la grande cloche pour entrer au Cauchemar depuis ces positions, élimine les Visions de Gahlran dans les deux couloirs et nettoie les Bellkeepers au centre.","Quand les Visions sont mortes, le vrai Gahlran devient vulnérable. Fais les dégâts puis rentre dans le cercle de sortie avant la fin du chronomètre."],"recovery":"Un Porteur tué par erreur peut réduire fortement le temps. Si le minuteur est bas, arrête les autres ennemis, tue les Bellkeepers de retour et rassemble toute l’équipe dans la cloche.","map":{"title":"Salle centrale et deux couloirs","nodes":[{"p":"entry","label":"Cloche|d’entrée","kind":"entry"},{"p":"center","label":"Gahlran|centre","kind":"boss"},{"p":"nw","label":"Porte|bannière A","kind":"goal"},{"p":"ne","label":"Porte|bannière B","kind":"goal"},{"p":"sw","label":"Cloche|de retour","kind":"safe"},{"p":"south","label":"Visions|à éliminer","kind":"danger"}],"links":[["entry","center"],["center","nw"],["center","ne"],["nw","sw"],["ne","sw"],["sw","south"],["south","center"]]}},{"title":"Le Caveau — trois Gardiens scellés","goal":"Pour chaque Gardien, lire les deux symboles demandés, récupérer les deux essences correspondantes au Cauchemar et les déposer pour briser son bouclier.","team":"À trois : deux coureurs de bannière et un joueur qui nettoie les Bellkeepers et protège le retour. Changez de coureur si le trajet devient dangereux.","steps":["Regarde les deux symboles au-dessus du Gardien invulnérable. Note-les avant d’activer la cloche ; ils déterminent les deux seules bannières à récupérer.","Dans le Cauchemar, tue les Porteurs correspondant aux symboles annoncés. Ne tue pas les autres : cela peut faire perdre un temps précieux.","Ramasse les essences de bannière et retourne à la cloche. Élimine les Bellkeepers qui bloquent la sortie, puis tire la cloche depuis son cercle avec toute l’équipe dedans.","Dans le monde matériel, dépose chaque essence sur sa bannière correspondante. Quand les deux sont validées, tue le Gardien maintenant vulnérable.","Répète pour les trois Gardiens. Après chaque victoire, relis les nouveaux symboles : ils peuvent être différents."],"recovery":"Si une bannière est déposée sur le mauvais symbole, ne pars pas en Cauchemar au hasard. Vérifie les symboles affichés et garde la prochaine transition pour compléter la paire correcte.","map":{"title":"Trois salles autour du centre","nodes":[{"p":"entry","label":"Cloche","kind":"entry"},{"p":"center","label":"Gardien|actif","kind":"boss"},{"p":"nw","label":"Bannière|gauche","kind":"goal"},{"p":"ne","label":"Bannière|droite","kind":"goal"},{"p":"sw","label":"Porteur|Cauchemar","kind":"danger"},{"p":"south","label":"Retour|cloche","kind":"safe"}],"links":[["entry","center"],["center","nw"],["center","ne"],["nw","south"],["ne","south"],["south","entry"]]}},{"title":"Caiatl — sonner les bonnes cloches","goal":"Récupérer quatre bannières, les déposer, puis étourdir Caiatl à la cloche qu’elle approche pour obtenir le vrai bonus de dégâts.","team":"À trois : l’équipe récupère les bannières en deux passages ; un joueur reste prêt près de la cloche ciblée, un autre nettoie les Bellkeepers, le troisième suit Caiatl et annonce sa direction.","steps":["Au monde matériel, lis les quatre symboles demandés. Dans le Cauchemar, tue les Porteurs correspondants et ramasse leurs essences, puis reviens par la cloche avec toute l’équipe dans son cercle.","Dépose les bannières sur les quatre supports. La salle est prête ; élimine les Bellkeepers autour des petites cloches.","Tire la grande cloche quand tout le monde est en position pour lancer la phase. Caiatl court vers l’une des petites cloches : suis-la et annonce laquelle.","Tue les Bellkeepers de cette cloche et place l’équipe dans son cercle. Quand Caiatl arrive, tire sur la cloche pour l’étourdir ; elle reçoit alors le bonus qui augmente les dégâts.","Inflige des dégâts pendant qu’elle est étourdie. Répète sur les cloches suivantes tant qu’elle se déplace, puis rejoins la sortie avant que le monde ne s’effondre."],"recovery":"Tirer une cloche trop tôt ne donne pas le bonus et gaspille l’occasion. Si Caiatl s’échappe, regroupement et nouvelle collecte : ne vous dispersez pas sur la mauvaise cloche.","map":{"title":"Caiatl choisit une cloche de l’anneau","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Caiatl|trajet mobile","kind":"boss"},{"p":"nw","label":"Petite|cloche 1","kind":"goal"},{"p":"ne","label":"Petite|cloche 2","kind":"goal"},{"p":"sw","label":"Petite|cloche 3","kind":"goal"},{"p":"south","label":"Grande cloche|départ","kind":"entry"},{"p":"se","label":"Retour|cloche","kind":"safe"}],"links":[["entry","south"],["south","center"],["center","nw"],["center","ne"],["center","sw"],["center","se"]]}}]},{"id":"spire-of-the-watcher","name":"Flèche du Veilleur","original":"Spire of the Watcher","summary":"Suivre les câbles d’énergie de l’Arctrician, alimenter les circuits et contrôler les phases de deux boss.","source":"https://destiny2.vaexil.tv/guides/dungeons/spire-of-the-watcher","route":["Dans les couloirs de la Flèche, fais attention aux chutes, aux plateformes suspendues et aux Vex qui tirent à distance. Les câbles jaunes restent visibles à travers les pièces : suis-les plutôt qu’un souvenir de route.","Le buff Arctrician vient des Minotaures de Conduit : tue-en un et marche dans sa flaque électrique. Seul un joueur avec ce buff peut activer les nœuds."],"encounters":[{"title":"Réactiver l’alimentation — quatre circuits","goal":"Obtenir Arctrician et suivre quatre circuits jaunes jusqu’à la trappe centrale.","team":"À trois : un joueur suit un câble à la fois, un autre élimine les Minotaures pour renouveler le buff, le troisième protège la route et confirme le nœud final.","steps":["Nettoie les ennemis de l’avant-poste et tue un Minotaure de Conduit. Marche dans sa flaque pour obtenir le buff Arctrician.","Trouve un nœud de départ avec une flèche qui indique le sens du câble. Tire dessus avec le buff, puis suis physiquement le câble jaune jusqu’au nœud suivant.","Continue dans l’ordre jusqu’au nœud près de la trappe centrale. Quand le circuit devient bleu, il est terminé ; sa progression ne se perd pas si le buff expire.","Retourne chercher un autre Minotaure si nécessaire et recommence depuis un départ différent pour les trois autres circuits.","Quand les quatre circuits sont bleus, la trappe centrale s’ouvre. Regroupe l’équipe puis descends."],"recovery":"Si un nœud ne s’allume pas, reprends au dernier segment bleu et cherche le premier nœud non alimenté. Ne tire pas sur plusieurs nœuds au hasard.","map":{"title":"Quatre câbles convergent vers la trappe","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Trappe|centrale","kind":"goal"},{"p":"nw","label":"Départ|bâtiment","kind":"room"},{"p":"ne","label":"Départ|toit","kind":"room"},{"p":"sw","label":"Départ|tunnel","kind":"room"},{"p":"se","label":"Départ|sol","kind":"room"}],"links":[["entry","nw"],["nw","center"],["entry","ne"],["ne","center"],["entry","sw"],["sw","center"],["entry","se"],["se","center"]]}},{"title":"Akelous — allumer les quatre tiges","goal":"Alimenter les quatre circuits de plateforme, casser les yeux rouges d’Akelous à la dernière tige et tirer sur son noyau exposé.","team":"À trois : répartissez les plateformes, un joueur garde le centre et renouvelle le buff. Avant le quatrième circuit, nettoyez les Harpies et placez toute l’équipe près de la tige qui terminera la séquence.","steps":["Tue le Minotaure de Conduit pour démarrer et obtenir Arctrician. Choisis une plateforme numérotée et suis son câble jaune depuis le centre jusqu’à sa tige.","Alimente chaque nœud dans le sens du câble. Les fils peuvent passer sous une passerelle ou autour d’un pilier : vérifie le vrai chemin avant de tirer.","Répète sur trois plateformes. Avant la quatrième, annonce le numéro de celle qui sera terminée en dernier et demande à l’équipe de la rejoindre.","Quand le quatrième circuit s’allume, Akelous se place près de cette tige. Brise rapidement les douze petits yeux rouges autour de son centre.","Quand ses yeux sont cassés, tire sur le noyau exposé pendant qu’il recule vers le centre. Éloigne-toi lorsque le souffle final se prépare."],"recovery":"Si le buff expire, renouvelle-le et continue le circuit : les nœuds déjà bleus restent validés. Si l’équipe est sur la mauvaise plateforme, prépare le prochain cycle sans gaspiller les munitions.","map":{"title":"Plateformes rayonnant depuis la tour","nodes":[{"p":"entry","label":"Centre|de la tour","kind":"entry"},{"p":"center","label":"Akelous|et tige finale","kind":"boss"},{"p":"nw","label":"Plateforme|1","kind":"goal"},{"p":"ne","label":"Plateforme|2","kind":"goal"},{"p":"sw","label":"Plateforme|3","kind":"goal"},{"p":"se","label":"Plateforme|4","kind":"goal"}],"links":[["entry","nw"],["entry","ne"],["entry","sw"],["entry","se"],["se","center"]]}},{"title":"Persys — purger le réacteur","goal":"Ouvrir le réacteur, alimenter ses circuits, faire entrer Persys dans la salle puis refermer les portes pour faire tomber son bouclier.","team":"À trois : un joueur connecte les nœuds, un attire les Minotaures et obtient Arctrician, un surveille la position du boss et appelle la fermeture des portes.","steps":["Distingue la salle de contrôle (côté ralliement) de la salle du réacteur (au-delà de la grande porte). Tue les Minotaures et prends Arctrician avant de toucher aux circuits.","Active les nœuds rouges du mécanisme dans la salle de contrôle pour ouvrir l’accès, puis relie les circuits jaunes requis dans les deux salles.","Quand le message de purge apparaît, fais entrer Persys dans le réacteur. Toute l’équipe ressort ensuite dans la salle de contrôle et ferme les portes en validant les nœuds.","Reste derrière la séparation pendant l’explosion du réacteur. Elle retire le bouclier de Persys : attaque son noyau pendant la fenêtre de dégâts.","Quand le bouclier revient, nettoie les ennemis, renouvelle Arctrician et répète le cycle de portes et de purge."],"recovery":"Ne reste pas dans le réacteur quand les portes se ferment : l’explosion est la mécanique qui enlève le bouclier, mais elle tue les joueurs restés à l’intérieur.","map":{"title":"Deux pièces séparées par une porte","nodes":[{"p":"entry","label":"Contrôle|côté départ","kind":"entry"},{"p":"center","label":"Porte|du réacteur","kind":"goal"},{"p":"north","label":"Réacteur|Persys","kind":"danger"},{"p":"west","label":"Circuit|gauche","kind":"room"},{"p":"east","label":"Circuit|droite","kind":"room"},{"p":"south","label":"Zone sûre|contrôle","kind":"safe"}],"links":[["entry","west"],["entry","east"],["west","center"],["east","center"],["center","north"],["center","south"]]}}]},{"id":"ghosts-of-the-deep","name":"Fantômes des profondeurs","original":"Ghosts of the Deep","summary":"Lire des runes de la Ruche, utiliser Deepsight et survivre aux trajets sous-marins à pression limitée.","source":"https://destiny2.vaexil.tv/guides/dungeons/ghosts-of-the-deep","route":["Sous l’eau, la pression monte. Rejoins régulièrement une bulle d’air ou un sas pressurisé ; ne pars pas seul dans une branche et attends que la bulle se recharge pour tout le monde.","Les vestiges sont portés en même temps qu’un compte à rebours. Le joueur qui tue un Lucent Hive doit écraser son Fantôme avant de prendre le vestige."],"encounters":[{"title":"Briser le rituel — les statues de la Ruche","goal":"Lire les runes révélées par les Lucent Hive, les retenir et déposer les vestiges sur les statues correspondantes.","team":"À trois : un lecteur garde la rune, un coureur récupère le vestige, un Gardien écrase le Fantôme et défend la statue. Répétez les rôles plutôt que de transporter plusieurs objets à l’aveugle.","steps":["Dans chaque salle de rituel, élimine le Lucent Hive marqué. Il laisse un Fantôme : approche-toi et utilise l’action de finition pour l’écraser.","Une rune apparaît après sa mort. Annonce-la et mémorise-la ; elle indique la statue de la Ruche où le vestige doit être déposé.","Ramasse le vestige, suis la route lumineuse vers la statue de même symbole et interagis jusqu’à la confirmation du dépôt.","Nettoie les ennemis, puis recommence avec les autres Lucent Hive. Les symboles doivent être lus pendant la tentative, car ils ne se devinent pas à l’avance.","Quand le rituel est terminé, élimine le boss et suis le chemin descendant vers les profondeurs sous-marines."],"recovery":"Si tu ne te souviens plus du symbole, retourne près de la statue ou relance Deepsight si la salle le permet. Ne dépose pas le vestige sur une statue choisie au hasard.","map":{"title":"Salle rituelle et statues autour","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Rituel|central","kind":"goal"},{"p":"nw","label":"Statue|rune 1","kind":"goal"},{"p":"ne","label":"Statue|rune 2","kind":"goal"},{"p":"sw","label":"Statue|rune 3","kind":"goal"},{"p":"south","label":"Lucent Hive|à vaincre","kind":"danger"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","sw"],["south","center"]]}},{"title":"Ecthar — runes sous-marines et bouclier","goal":"Lire trois runes, les toucher dans le labyrinthe sous-marin, déposer trois vestiges sur les statues, puis utiliser le puits d’un Wellkeeper pour blesser Ecthar.","team":"À trois : un lecteur prend les runes, un coureur les touche sous l’eau, un joueur écrase les Fantômes des Sorcières et prépare le puits de dégâts.","steps":["Utilise Deepsight pour voir les runes allumées sur les murs gauche et droit. Note les trois symboles avant de plonger.","Descends dans le labyrinthe et touche uniquement les runes notées. Suis les bulles et sas pour faire baisser la pression ; remonte vers l’arène quand les trois sont validées.","Les Sorcières Lucent apparaissent. Tue-les, écrase leur Fantôme, prends le vestige et dépose-le sur la statue dont la rune correspond à celle qui a été lue.","Après trois dépôts, élimine le Wellkeeper Knight. Son puits permet de briser le bouclier d’Ecthar ; regroupe-toi au bon endroit avant de l’activer.","Quand Ecthar devient vulnérable, tire sur le boss sans te faire coincer près de son bouclier. À son retour d’immunité, relis les runes et recommence."],"recovery":"Ne touche pas une rune inconnue sous l’eau : note d’abord les trois murs éclairés. Si la pression est haute, prends la bulle la plus proche avant de continuer.","map":{"title":"Arène sèche au-dessus du labyrinthe","nodes":[{"p":"entry","label":"Ralliement|arène","kind":"entry"},{"p":"center","label":"Ecthar|fontaine","kind":"boss"},{"p":"nw","label":"Statue|gauche","kind":"goal"},{"p":"ne","label":"Statue|droite","kind":"goal"},{"p":"north","label":"Statue|fond","kind":"goal"},{"p":"south","label":"Plongée|vers les runes","kind":"danger"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","north"],["center","south"]]}},{"title":"Šimmumah — Oryx et les trois vestiges","goal":"Utiliser Deepsight sur les marques du corps d’Oryx, tuer Vorlog dans la zone rituelle, lire une rune puis ramener le vestige correspondant.","team":"À trois : un lecteur annonce la partie du corps activée, un joueur suit le rituel et le groupe se répartit sur les trois chambres Lucent Hive.","steps":["Active Deepsight près du corps d’Oryx et note les trois zones lumineuses : cœur, tête, main, genou ou pied. Ces zones désignent où faire apparaître le rituel.","Dans la zone active, le lecteur se place dans l’anneau rituel pendant que l’équipe tue Vorlog. Attire-le vers sa mort dans cet anneau pour révéler une rune.","Entre dans la chambre inondée qui porte cette rune. Tue le Lucent Hive, écrase son Fantôme et prends le vestige correspondant.","Retourne au corps d’Oryx et dépose le vestige sur la marque dont la rune correspond. Répète jusqu’à valider les trois marques.","Une fois les trois vestiges déposés, brise le bouclier de Šimmumah et attaque-la. Reste prêt à refaire la lecture après sa prochaine phase d’immunité."],"recovery":"Si la rune ne correspond pas au corps que tu visais, vérifie l’anneau rituel et la chambre : ne lie pas une rune à un type d’ennemi fixe, elle change d’une séquence à l’autre.","map":{"title":"Le corps d’Oryx et trois chambres","nodes":[{"p":"entry","label":"Entrée|du rituel","kind":"entry"},{"p":"center","label":"Corps|d’Oryx","kind":"goal"},{"p":"nw","label":"Chambre|gauche","kind":"room"},{"p":"ne","label":"Chambre|droite","kind":"room"},{"p":"north","label":"Chambre|fond","kind":"room"},{"p":"south","label":"Anneau|de Vorlog","kind":"danger"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","north"],["center","south"]]}}]},{"id":"warlords-ruin","name":"Ruines du seigneur de guerre","original":"Warlord’s Ruin","summary":"Capturer les totems des Corrompus, obtenir des charges solaires et gérer une malédiction à chaque boss.","source":"https://destiny2.vaexil.tv/guides/dungeons/warlords-ruin","route":["Dans la prison, observe les deux squelettes : les traits près de leurs mains indiquent combien de cadrans tourner dans chaque sens. Les deux nombres font six. Tourne les cadrans puis active le levier.","Les totems sont des anneaux blancs autour d’une flaque noire : reste dedans jusqu’à ce que la flaque disparaisse. Un Totem capturé ouvre la vulnérabilité ou donne une charge solaire selon la rencontre.","Pendant les dégâts du Locus, le froid Biting Cold tue à dix charges. Passe par les abris chauffés extérieurs entre les braseros."],"encounters":[{"title":"Rathil — la cage et les totems","goal":"Détruire les yeux corrompus dans les cages, purifier les totems avant la fin d’Imminent Wish et attaquer Rathil pendant le buff obtenu.","team":"À trois : un joueur surveille les yeux, un repère et capture les totems, un nettoie les Corrompus. Les yeux sont partagés entre les cages : aide le joueur qui annonce son dernier œil.","steps":["Engage Rathil et élimine les ennemis jusqu’à l’alerte Imminent Wish. Avant d’être téléporté, repère le premier totem apparu et annonce sa position.","Dans la cage suspendue, cherche trois Blighted Eyes autour de toi : regarde au-dessus, au-dessous du rebord et sur les côtés. Détruis-les pour ouvrir la cage.","Descends vers le totem annoncé et reste dans son anneau blanc jusqu’à ce que la flaque noire disparaisse. Un second totem peut apparaître : capture-le aussi si le temps le permet.","Quand le compte à rebours arrive à zéro, les totems capturés donnent Naeem’s Wish Empowerment. Rathil devient vulnérable : regroupe-toi et attaque.","Quand le bouclier revient, élimine les ennemis, relis le prochain totem et recommence."],"recovery":"Si un œil manque, aide un autre joueur depuis une position sûre. Ne reste pas dans la cage qui monte vers les pointes ; sortir de la cage est prioritaire sur le DPS.","map":{"title":"Cages autour du boss, totems au sol","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Rathil","kind":"boss"},{"p":"nw","label":"Cage|gauche","kind":"danger"},{"p":"ne","label":"Cage|droite","kind":"danger"},{"p":"sw","label":"Totem|gauche","kind":"goal"},{"p":"se","label":"Totem|droite","kind":"goal"},{"p":"south","label":"Zone|de sortie","kind":"safe"}],"links":[["entry","center"],["center","nw"],["center","ne"],["nw","sw"],["ne","se"],["sw","south"],["se","south"]]}},{"title":"Locus of Wailing Grief — quatre braseros","goal":"Capturer des totems pour créer quatre charges solaires, les déposer dans les braseros puis se déplacer d’un brasero à l’autre pendant les dégâts.","team":"À trois : un joueur par côté contrôle les Chieftains et totems, le troisième annonce le froid, aide les captures et organise les dépôts. Fixez le sens de rotation avant le premier brasero.","steps":["Détruis l’œil corrompu de départ et élimine les vagues qui arrivent. Les yeux font apparaître un Chieftain de chaque côté.","Affaiblis chaque Chieftain jusqu’à ce qu’il lance son totem, puis tue-le. Capturer l’anneau de son totem donne une charge solaire quand le compte à rebours expire.","Surveille Biting Cold. À forte charge, quitte le totem et traverse un abri chauffant extérieur jusqu’à la disparition du débuff ; à dix charges, le froid tue.","Après l’expiration, ramasse les charges solaires et dépose-les dans les braseros centraux encore éteints. Il faut quatre dépôts pour lancer les dégâts.","Pendant les dégâts, reste près du brasero actif puis suis l’indication de l’équipe vers le suivant. Continue de te réchauffer entre les zones si ton froid monte.","Quand le boss redevient immunisé, recommence les yeux et les totems jusqu’à sa défaite."],"recovery":"Ne pars pas au brasero si le froid est presque mortel : chauffe-toi d’abord. Si un brasero est déjà allumé, choisis le suivant annoncé et ne dépense pas la charge ailleurs.","map":{"title":"Anneau extérieur chauffant et 4 feux","nodes":[{"p":"entry","label":"Départ","kind":"entry"},{"p":"center","label":"Locus|zone centrale","kind":"boss"},{"p":"nw","label":"Chieftain|gauche","kind":"danger"},{"p":"ne","label":"Chieftain|droite","kind":"danger"},{"p":"sw","label":"Abri|chauffant","kind":"safe"},{"p":"se","label":"Abri|chauffant","kind":"safe"},{"p":"north","label":"Braseros|1 à 4","kind":"goal"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","north"],["nw","sw"],["ne","se"]]}},{"title":"Hefnd — les trois étages et l’anneau","goal":"Capturer les totems, transférer la malédiction aux Hex-Drinkers, avancer chaque palier de vie puis attaquer Hefnd depuis les îlots du haut.","team":"À trois : un joueur suit la malédiction et ses porteurs, un capture les totems, un nettoie les ennemis et lit les yeux corrompus. Les porteurs d’Hex doivent être annoncés immédiatement.","steps":["Sur chaque grande plateforme, détruis les yeux corrompus puis élimine les Chieftains pour faire apparaître des totems. Capture les anneaux blancs avant la fin du compte à rebours.","Un joueur touché par Hex of Vengeful Corruption porte une malédiction. Repère les Hex-Drinkers et transfère-la au bon ennemi avant qu’elle n’explose sur le groupe.","Les totems capturés donnent l’accès au bonus qui permet de pousser la barre de vie au-delà du verrou. Attaque Hefnd seulement quand l’équipe confirme que la phase de dégâts est ouverte.","Quand la barre s’arrête, suis la route vers l’étage supérieur et refais la séquence. Le combat descend puis remonte vers les plateformes de l’anneau supérieur.","Au dernier anneau, utilise les trois îlots comme positions de combat et termine Hefnd avant la fin de la phase."],"recovery":"Si la barre de vie se bloque, ce n’est pas un bug : l’étape exige un nouveau totem et le transfert de malédiction. Arrête le tir, sécurise l’étage et prépare le prochain palier.","map":{"title":"Combat en montée de plateformes","nodes":[{"p":"entry","label":"Plateforme|basse","kind":"entry"},{"p":"center","label":"Hefnd","kind":"boss"},{"p":"nw","label":"Totem|1","kind":"goal"},{"p":"ne","label":"Totem|2","kind":"goal"},{"p":"north","label":"Palier|supérieur","kind":"room"},{"p":"sw","label":"Hex-Drinker","kind":"danger"},{"p":"se","label":"Anneau|trois îlots","kind":"safe"}],"links":[["entry","nw"],["entry","ne"],["nw","center"],["ne","center"],["center","north"],["north","se"],["sw","center"]]}}]},{"id":"vespers-host","name":"L’Hôte de Vesper","original":"Vesper’s Host","summary":"Récupérer les augmentations Scanner, Opérateur et Suppresseur, lire les panneaux et transporter des noyaux.","source":"https://destiny2.vaexil.tv/guides/dungeons/vespers-host","route":["Une augmentation est un rôle temporaire récupéré sur un porteur marqué. Un terminal permet de la déposer puis de la reprendre ; annonce le rôle et les panneaux avant d’utiliser l’augmentation.","Un noyau nucléaire impose un compte de radiation. Passe-le à un coéquipier avant le niveau critique ou dépose-le dans une zone sûre, puis reprends-le après récupération."],"encounters":[{"title":"Libérer la station — trois noyaux","goal":"Ouvrir les branches du Cerveau, des Poumons et du Cœur, libérer un noyau dans chaque branche et les ramener aux trois réceptacles centraux.","team":"À trois : Scanner lit les panneaux blancs, Opérateur tire uniquement les panneaux annoncés, Suppresseur protège les trajets et aide les noyaux. Une augmentation peut être déposée sur un terminal pour être relayée.","steps":["Interagis avec la sphère de l’IA pour redémarrer le système, puis élimine la première vague et le Brig central.","Prends l’augmentation Scanner sur le porteur marqué. Dans chaque branche, approche les panneaux numérotés et annonce ceux qui deviennent blancs : ils indiquent les bonnes cibles.","Fais récupérer Opérateur par le joueur désigné et tire uniquement sur la liste confirmée. Les tirs ouvrent les barrières du trajet ; élimine les ennemis entre les panneaux.","Continue jusqu’au distributeur de noyau. Dépose les augmentations aux terminaux pour les reprendre plus tard, puis transporte le noyau vers l’IA en surveillant la radiation.","Répète dans les trois branches, une pour le Cerveau, une pour les Poumons et une pour le Cœur. Dépose chaque noyau dans un réceptacle différent derrière la sphère centrale."],"recovery":"Si une barrière ne s’ouvre pas, vérifie tous les panneaux annoncés et le compte de la liste. Si la radiation approche dix, passe le noyau à un joueur frais et laisse le débuff retomber.","map":{"title":"Hub central et trois branches","nodes":[{"p":"entry","label":"Sas|de départ","kind":"entry"},{"p":"center","label":"Sphère IA|3 dépôts","kind":"goal"},{"p":"nw","label":"Cerveau","kind":"room"},{"p":"ne","label":"Poumons","kind":"room"},{"p":"south","label":"Cœur","kind":"room"},{"p":"north","label":"Distributeur|de noyau","kind":"goal"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","south"],["nw","north"],["ne","north"],["south","north"]]}},{"title":"Raneiks Unified — séparer le Serviteur","goal":"Utiliser Suppresseur pour révéler les composants de Raneiks, lire leurs numéros, puis Opérateur active les quatre panneaux correspondants.","team":"À trois : un Suppresseur attire le boss sous les hologrammes, un Scanner relève les numéros, un Opérateur tire les panneaux. Éliminez les Vandals avant chaque séquence.","steps":["Élimine les ennemis marqués et récupère les augmentations. Le Suppresseur se place sous un hologramme de Raneiks et utilise son action lorsque le boss passe à proximité.","Raneiks se sépare brièvement en plusieurs Serviteurs. Le Scanner lit les numéros des quatre composants qui doivent être ciblés ; annonce-les sans confondre leur ordre.","Le joueur Opérateur trouve les panneaux muraux avec ces numéros et tire uniquement sur ces quatre panneaux.","Répète la séquence de Suppresseur, lecture et tirs jusqu’à l’ouverture de la phase de dégâts.","Quand le boss se regroupe au centre, l’équipe fait une courte phase de dégâts en restant proche et prête à changer de position. Recommence si sa santé ne tombe pas à zéro."],"recovery":"Si un mauvais panneau a été tiré, arrête les tirs et refais une lecture complète au prochain passage. N’essaie pas de deviner un numéro à partir de sa position.","map":{"title":"Boss au centre, panneaux sur le mur","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Raneiks|hologrammes","kind":"boss"},{"p":"nw","label":"Panneaux|mur gauche","kind":"goal"},{"p":"ne","label":"Panneaux|mur droit","kind":"goal"},{"p":"south","label":"Terminal|augmentations","kind":"safe"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","south"]]}},{"title":"Puppeteer corrompu — purger les deux côtés","goal":"Utiliser les trois augmentations pour descendre, remplir les purges sur les deux moitiés, retirer le bouclier puis survivre aux impulsions d’anomalie.","team":"À trois : un Scanner lit les cibles, un Opérateur ouvre les barrières et un Suppresseur déclenche les hologrammes. Gardez un noyau de pantin pour la première impulsion et la trappe de sortie pour la seconde.","steps":["Dans la salle supérieure, récupère Scanner, Opérateur et Suppresseur sur les ennemis marqués. Utilise chaque terminal pour ouvrir le chemin vers les Lower Stacks.","Descends et lis les cibles avec Scanner. Opérateur tire les panneaux correspondants ; Suppresseur utilise ses hologrammes pour exposer les noyaux et déclencher les consoles.","Répète jusqu’à ce que les deux moitiés de la salle aient terminé leur purge. Le bouclier du Puppeteer tombe ; retourne à la zone supérieure.","Suis le boss pendant la phase mobile et inflige des dégâts en restant vigilant aux pantins. Quand l’anomalie approche, détruis un pantin lumineux et reste près de son noyau pour survivre à la première impulsion.","Avant la seconde impulsion, rejoins la trappe au sol et tombe dans le conduit. Répète la purge et les dégâts jusqu’à la défaite du boss."],"recovery":"Si tu rates l’abri de l’anomalie, ne reste pas au milieu de l’arène. Si une purge est incomplète, retourne utiliser les terminaux et panneaux de la moitié manquante.","map":{"title":"Deux niveaux, salle basse puis trappe","nodes":[{"p":"entry","label":"Salle|supérieure","kind":"entry"},{"p":"center","label":"Puppeteer|mobile","kind":"boss"},{"p":"nw","label":"Purge|moitié gauche","kind":"goal"},{"p":"ne","label":"Purge|moitié droite","kind":"goal"},{"p":"south","label":"Trappe|d’évacuation","kind":"safe"},{"p":"north","label":"Noyau|pantin","kind":"goal"}],"links":[["entry","nw"],["entry","ne"],["nw","center"],["ne","center"],["center","north"],["center","south"]]}}]},{"id":"sundered-doctrine","name":"Doctrine brisée","original":"Sundered Doctrine","summary":"Résoudre des vérités de glyphes, des roues de symboles et des faisceaux dans la pyramide.","source":"https://destiny2.vaexil.tv/guides/dungeons/sundered-doctrine","route":["Avant le Riddle, passe par la galerie des glyphes : approche les symboles pour lire leur nom officiel dans le HUD. Utilise toujours ce nom dans les appels, pas une ressemblance visuelle.","Dans le labyrinthe, observe une fois le cycle des rochers avant de courir. Pour les roues, lis le symbole affiché et le sens de rotation ; le nombre de splinters donne la distance, pas un bonus de puissance."],"encounters":[{"title":"The Riddle — compléter les phrases","goal":"Lire les symboles manquants, vaincre le Truthspeaker qui révèle la bonne réponse, puis relier une source lumineuse à la cible glyphée correcte.","team":"À trois : un lecteur note phrase et cible, un coureur installe les lentilles, un Gardien nettoie les Subjugators et protège la route. Dites la destination avant d’activer la source.","steps":["Depuis l’entrée, lis la phrase à trois glyphes sur l’écran du fond et compte ses espaces vides. Les quatre salles latérales montrent les glyphes cibles ; repère leur nom avec le HUD.","Élimine le Truthspeaker marqué (un Grim important). Le glyphe révélé fournit le mot manquant de la phrase ; annonce le nom et la salle latérale qui porte ce symbole.","Pars de la cible et remonte le trajet vers une source centrale. Les ennemis porteurs de lentilles laissent les objets qui permettent d’orienter les supports lumineux.","Installe les lentilles nécessaires et oriente chaque miroir avant d’allumer la source. Vérifie le trajet complet, du départ à la cible, pour éviter un rayon qui part dans la mauvaise salle.","Active la source et attends le message de validation. La première manche demande une vérité, la deuxième deux, la troisième trois.","Si un rayon touche une fausse cible, élimine le Tormentor apparu, relis la phrase et reconstruis uniquement le chemin incorrect."],"recovery":"Ne tourne pas les lentilles au hasard après activation : certaines se brisent après plusieurs rotations. Planifie le chemin quand le rayon est éteint.","map":{"title":"Trois sources, quatre salles cibles","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Phrase|à compléter","kind":"goal"},{"p":"nw","label":"Cible|proche gauche","kind":"goal"},{"p":"ne","label":"Cible|proche droite","kind":"goal"},{"p":"sw","label":"Cible|loin gauche","kind":"goal"},{"p":"se","label":"Cible|loin droite","kind":"goal"},{"p":"north","label":"Sources|et lentilles","kind":"room"}],"links":[["entry","center"],["north","center"],["center","nw"],["center","ne"],["center","sw"],["center","se"]]}},{"title":"Zoetic Lockset — quatre roues et quatre yeux","goal":"Régler les roues pour que trois panneaux enregistrent Stop et le dernier Kill, puis blesser les Shriekers ouverts pendant la phase de dégâts.","team":"À trois : un lecteur annonce le regard du Shrieker, un opérateur règle les roues avec les splinters, un joueur contrôle les vagues et les dégâts. Les panneaux se remplissent de droite à gauche.","steps":["Observe les quatre roues, leur symbole actuel et le Shrieker qui est sur le point de les lire. Note aussi le panneau qui se remplira ensuite : le premier verrou apparaît à droite.","Quand le symbole Stop est demandé, récupère le bon nombre de Resonance Splinters et dépose-les pour amener la roue sur Stop. Si elle tourne dans le mauvais sens, tire sur son crux proche pour inverser le sens.","Laisse le Shrieker lire Stop, puis vérifie le panneau large qui vient de s’allumer. Répète dans l’ordre jusqu’à verrouiller trois Stop.","Pour le dernier panneau, règle une roue sur Kill. Quand l’effet Kill est lu et que la phase s’ouvre, choisis un Shrieker dont la coque est ouverte.","Les quatre Shriekers partagent la même barre de vie. Change de cible dès qu’un œil se referme et continue d’attaquer un autre œil ouvert."],"recovery":"Si la roue a avancé d’un nombre incorrect de cases, relis son symbole actuel et recalcule le prochain mouvement. Si un Shrieker se ferme, change simplement de cible : la vie est partagée.","map":{"title":"Quatre roues font face aux panneaux","nodes":[{"p":"entry","label":"Ralliement","kind":"entry"},{"p":"center","label":"Panneaux|de verrouillage","kind":"goal"},{"p":"nw","label":"Roue +|Shrieker 1","kind":"room"},{"p":"ne","label":"Roue +|Shrieker 2","kind":"room"},{"p":"sw","label":"Roue +|Shrieker 3","kind":"room"},{"p":"se","label":"Roue +|Shrieker 4","kind":"room"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","sw"],["center","se"]]}},{"title":"Kerrev — la vérité et les six glyphes","goal":"Identifier quelle phrase à trois glyphes est vraie, éclairer les trois glyphes de la phrase fausse et survivre au feu de la pyramide pour retirer le bouclier.","team":"À trois : un lecteur suit le Truthspeaker et la colonne vraie, un joueur règle les lentilles dans les salles gauche/droite, un défenseur nettoie et annonce l’activation du console.","steps":["Lis les deux colonnes de trois glyphes au-dessus de Kerrev : une phrase est vraie, l’autre fausse. Tue le Truthspeaker dans l’une des salles latérales ; son glyphe apparaît dans la colonne vraie.","Annonce clairement quelle colonne est vraie, puis considère l’autre comme fausse. Le but de la mécanique est d’allumer les trois glyphes de la phrase fausse et de laisser ceux de la phrase vraie éteints.","Fais circuler les lentilles depuis leurs salles vers les cibles nécessaires. Remonte le chemin depuis chaque glyphe cible jusqu’à la source et vérifie toutes les orientations avant d’activer.","Quand les six états sont corrects, active le console et éloigne-toi des lignes de feu de la pyramide. La salve passe ; le bouclier de Kerrev tombe.","Inflige des dégâts au boss. Quand il redevient immunisé, recommence la lecture et la configuration pour le prochain cycle."],"recovery":"Si tu ignores quelle phrase est vraie, ne devine pas : élimine le Truthspeaker actif. Si une lentille manque, retrace la route depuis la cible et cherche la salle qui doit fournir un porteur.","map":{"title":"Boss et affichage à six glyphes","nodes":[{"p":"entry","label":"Entrée","kind":"entry"},{"p":"center","label":"Kerrev +|phrases","kind":"boss"},{"p":"nw","label":"Salle|gauche","kind":"room"},{"p":"ne","label":"Salle|droite","kind":"room"},{"p":"south","label":"Console|à activer","kind":"goal"},{"p":"north","label":"Lentilles|et sources","kind":"safe"}],"links":[["entry","center"],["center","nw"],["center","ne"],["nw","south"],["ne","south"],["north","center"]]}}]},{"id":"equilibrium","name":"Equilibrium","original":"Equilibrium","summary":"Une aventure dans les terres Renegades : Shadow Power, Harvester, panneaux Taken et alternance entre deux royaumes.","source":"https://destiny2.vaexil.tv/guides/dungeons/equilibrium","route":["Dans les salles de la Harvester, les zones de largage de modules Cabal sont indiquées au sol : sors-en avant l’impact. Les connecteurs peuvent être ouverts en attirant le tir d’un Apprentice sur leur pylône.","Les flaques Taken donnent des rangs d’ombre. Répète l’action jusqu’au rang annoncé avant d’utiliser Shadow Power sur un ennemi ou panneau."],"encounters":[{"title":"Board the Harvester — les Apprentices et Behemoths","goal":"Ouvrir un passage à vélo, monter au rang Shadow Novice, interrompre six Nameless Apprentices et détruire neuf Behemoths.","team":"À trois : un joueur ouvre un connecteur et conduit le Piker Bike, un interrompt les Apprentices, un contrôle les Behemoths et les zones de largage.","steps":["Interagis avec la commande centrale de la Harvester pour commencer. Élimine la première vague en quittant les cercles marqués où les capsules Cabal vont s’écraser.","Repère un Nameless Apprentice invulnérable. Attire son grand tir Taken vers un pylône-connecteur en plaçant le pylône entre toi et lui ; sors de sa ligne avant l’impact.","Le connecteur détruit ouvre une barrière rouge. Prends le Piker Bike derrière elle et traverse le tunnel pour commencer à accumuler Shadow dans les flaques.","Ramasse les flaques jusqu’au rang Shadow Novice. Quand un Apprentice s’arrête et charge son tir lumineux, approche-toi et utilise Shadow Power pour l’interrompre, puis élimine-le.","Continue jusqu’à six Apprentices et neuf Behemoths détruits. Le groupe qui n’a pas le vélo évite les zones de largage et protège le coureur à son retour."],"recovery":"Si le tir de l’Apprentice manque le connecteur, replace le pylône entre lui et la cible et attends sa prochaine charge. Ne saute pas pendant le déplacement spatial du vaisseau : attends qu’il soit stable.","map":{"title":"Harvester au centre, barrières autour","nodes":[{"p":"entry","label":"Ralliement","kind":"entry"},{"p":"center","label":"Harvester","kind":"goal"},{"p":"nw","label":"Connecteur|gauche","kind":"room"},{"p":"ne","label":"Connecteur|droite","kind":"room"},{"p":"sw","label":"Barrière|rouge","kind":"danger"},{"p":"se","label":"Piker Bike","kind":"safe"},{"p":"north","label":"Apprentices|et capsules","kind":"danger"}],"links":[["entry","center"],["center","nw"],["center","ne"],["nw","sw"],["sw","se"],["center","north"]]}},{"title":"Harrow — neuf panneaux et purge Arc","goal":"Atteindre Shadow Apprentice, activer les trois panneaux de chacune des trois salles extérieures, attirer Harrow dans les pièges Arc puis retirer son bouclier.","team":"À trois : un opérateur active les panneaux, un nettoie les Centurions et Psions, un attire Harrow dans les fosses et prépare un conducteur pour prolonger les dégâts.","steps":["Dans les salles extérieures, tue les Lackeys et ramasse leurs flaques jusqu’au rang Shadow Apprentice. Ce rang est nécessaire pour activer les panneaux Taken.","Dans chaque salle gauche, droite et arrière, repère les trois panneaux avant d’en toucher un. Utilise Shadow Power sur les trois dans le temps imparti et vérifie que les lumières au-dessus de la porte passent au vert.","Harrow peut apparaître dans le couloir et préparer une explosion. Interromps-le avec Shadow Power ou éloigne-toi suffisamment, puis retourne finir les panneaux des trois salles.","Au centre, ouvre une fosse Arc en tirant sur le conduit au-dessus de sa porte. Attire Harrow au-dessus de la fosse ; chaque déclenchement retire une partie de son bouclier.","Répète avec les fosses jusqu’à ce que le bouclier tombe. Attaque le boss et attire son attaque vers un conducteur préchargé si vous voulez prolonger la fenêtre."],"recovery":"Si une salle n’est pas validée, inspecte plafond, murs et rebords : un panneau peut être en hauteur. Si une fosse se referme sans toucher Harrow, rouvre-la et réessaie.","map":{"title":"Salle centrale et trois ailes","nodes":[{"p":"entry","label":"Entrée|contrôle","kind":"entry"},{"p":"center","label":"Harrow|salle centrale","kind":"boss"},{"p":"nw","label":"Salle|gauche • 3","kind":"goal"},{"p":"ne","label":"Salle|droite • 3","kind":"goal"},{"p":"north","label":"Salle|arrière • 3","kind":"goal"},{"p":"south","label":"Fosses|Arc","kind":"danger"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","north"],["center","south"]]}},{"title":"Dredgen Sere — dix objectifs, deux royaumes","goal":"Dans le monde matériel, interrompre les Apprentices pour briser cinq orbes. Dans l’Ascendant, résoudre cinq ombres, puis rétracter les bobines avant le dernier orbe et les dégâts.","team":"À trois : un joueur gère les rangs d’ombre et les orbes, un suit les ombres de l’Ascendant, un protège le groupe, surveille les bobines et interrompt l’attaque des mains de Sere.","steps":["Dans le monde matériel, tue les Lackeys d’Incendior et ramasse leurs flaques pour atteindre le rang d’ombre requis. Quand un Apprentice brille et charge, utilise Shadow Power pour le rendre vulnérable, puis tue-le.","Chaque Apprentice vaincu déverrouille un orbe mural. Détruis-le rapidement pour prolonger le temps. Répète pour cinq orbes ; interromps l’attaque de Sere en tirant sur ses deux mains lumineuses.","Quand le groupe passe dans le royaume Ascendant, trouve les cinq Blistered Shadows : une au centre, une en hauteur, trois autour de l’anneau. Détruis chacune ou utilise l’action Compel si ton rang le permet ; ses deux choix donnent une durée et un plafond de dégâts différents.","Chaque ombre résolue déverrouille un autre orbe. Utilise les panneaux Taken pour faire apparaître les plateformes, notamment pour atteindre l’ombre en hauteur. Termine cinq objectifs puis passe dans l’autre royaume jusqu’à détruire dix orbes au total.","Avant le dixième et dernier orbe, vérifie les bobines Arc abaissées au plafond. Utilise Shadow Power sur le panneau associé à chacune pour les rétracter ; le dernier orbe lance les dégâts immédiatement.","Détruis le dernier orbe, attaque Sere et déplace-toi hors des zones électriques. Si le boss devient immunisé avec du temps restant, la limite de santé de cette phase est atteinte : prépare le cycle suivant."],"recovery":"Si le centre est électrifié, sors sur l’anneau extérieur et rétracte les bobines par leurs panneaux. Si une ombre est inaccessible, active les panneaux voisins pour créer ses plateformes.","map":{"title":"Royaumes matériel et Ascendant","nodes":[{"p":"entry","label":"Salle|matérielle","kind":"entry"},{"p":"center","label":"Sere","kind":"boss"},{"p":"nw","label":"5 orbes|muraux","kind":"goal"},{"p":"ne","label":"Bobines|Arc","kind":"danger"},{"p":"sw","label":"Portail|Ascendant","kind":"room"},{"p":"se","label":"Ombres|à résoudre","kind":"goal"},{"p":"north","label":"Orbes|Ascendants","kind":"goal"}],"links":[["entry","center"],["center","nw"],["center","ne"],["center","sw"],["sw","se"],["se","north"],["north","center"]]}}]}];

