  function addOptions(filter){
    var before=dungeonSelect.value;
    dungeonSelect.replaceChildren();
    var found=0;
    DONJONS.forEach(function(d,i){
      if(filter&&!((d.name+" "+d.original).toLocaleLowerCase("fr").includes(filter.toLocaleLowerCase("fr"))))return;
      var o=el("option","",d.name+" — "+d.original);o.value=String(i);dungeonSelect.appendChild(o);found++;
    });
    if(!found){var o=el("option","","Aucun donjon trouvé");o.value="-1";dungeonSelect.appendChild(o);dungeonSelect.value="-1";return false;}
    var chosen=Number(before);
    if(!Number.isFinite(chosen)||!DONJONS[chosen]||!(DONJONS[chosen].name+" "+DONJONS[chosen].original).toLocaleLowerCase("fr").includes((filter||"").toLocaleLowerCase("fr")))chosen=Number(dungeonSelect.options[0].value);
    dungeonSelect.value=String(chosen);return true;
  }
